insert into public.content_documents (collection, key, data, sort_order) values ('guides', 'register-your-address', $seed${"slug":"register-your-address","title":{"en":"Register your address","ne":"आफ्नो ठेगाना दर्ता गर्नुहोस्","hi":"अपना पता पंजीकृत करें"},"term":{"term":"Anmeldung"},"stage":"first30","readingMinutes":6,"lastVerified":"2026-10-14","summary":{"what":{"en":"Telling the city where you live. You get a paper you need for almost everything else."},"when":{"en":"Every time you move into a new flat."},"deadline":{"en":"Within 2 weeks of moving in"}},"steps":[{"title":{"en":"Get the landlord’s confirmation"},"body":{"en":"Your landlord signs a form saying you moved in. Ask for it when you get the keys."},"term":{"term":"Wohnungsgeberbestätigung"}},{"title":{"en":"Book an appointment at the citizen’s office"},"body":{"en":"Leipzig releases new slots online. Any office in the city works."},"cost":{"en":"Free"},"wait":{"en":"[X–Y days]"}},{"title":{"en":"Go to the appointment"},"body":{"en":"You leave with your registration certificate. The bank and the immigration office will ask for it."},"term":{"term":"Meldebescheinigung"}}],"documents":[{"en":"Passport with visa"},{"en":"Landlord’s confirmation"},{"en":"Registration form, filled in"}],"callouts":[{"kind":"tip","text":{"en":"No slots? Check the booking page early in the morning — cancelled slots often come back then."}},{"kind":"warning","text":{"en":"Moving again? You must register the new address too, and deregister when you leave Germany."}},{"kind":"mistake","text":{"en":"Waiting for a slot doesn’t pause the 2 weeks. Book on day one, even if the slot is later."}}],"related":[{"kind":"tool","title":{"en":"Compare bank accounts"},"href":"/tools/compare/bank-accounts"},{"kind":"guide","title":{"en":"Get your tax ID"},"href":"/guides/get-your-tax-id"}],"sources":[{"title":"Stadt Leipzig — Anmeldung","url":"https://www.leipzig.de/"},{"title":"Federal Registration Act (Bundesmeldegesetz)","url":"https://www.